-- NOT LOADED. Kept as a record of what left the design and why. GENERATED by tools/split.py.
-- cursor per consumer service: fanout, automation, search, audit, webhooks. ASSUMED.
-- A consumer must trail by a small safety window (or use pg_snapshot xmin) because nextval order != commit order.
CREATE TABLE event_consumers (
  consumer text PRIMARY KEY,
  last_seq bigint NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

INSERT INTO event_consumers (consumer) VALUES ('notification_fanout'),('automation'),('search_indexer'),('audit'),('webhooks')
  ON CONFLICT DO NOTHING;

-- scheduler (global)
CREATE TABLE automation_webhooks (                   -- ASSUMED: 'Webhook received' trigger; store only a hash of the secret
  id uuid PRIMARY KEY,
  automation_id uuid NOT NULL REFERENCES automations(id) ON DELETE CASCADE,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  secret_hash bytea NOT NULL,
  last_received_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX automation_webhooks_rule ON automation_webhooks (workspace_id, automation_id);

-- =============================================================================
-- 9. SEARCH (phase 1 = Postgres full-text)
-- =============================================================================
-- All searchable entities (tasks, comments, doc pages, docs, goals) are flattened into one table by the search indexer
-- (consumer 'search_indexer' on change_log). One GIN-indexed tsvector, one permission filter. ASSUMED (own design page, section 8).
-- PARTITION BY HASH (workspace_id) x 8 keeps each GIN small.
CREATE TABLE search_documents (
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  entity_type text NOT NULL CHECK (entity_type IN ('task','comment','doc','page','goal','attachment')),
  entity_id uuid NOT NULL,
  title text NOT NULL DEFAULT '',
  body text NOT NULL DEFAULT '',
  acl_node_ids uuid[] NOT NULL DEFAULT '{}',         -- entity + its ancestors (space, folder, list): permission filter by reachable nodes
  tsv tsvector GENERATED ALWAYS AS (
        setweight(to_tsvector('simple', coalesce(title,'')), 'A') ||
        setweight(to_tsvector('simple', coalesce(body,'')),  'B')) STORED,
  source_version integer NOT NULL DEFAULT 0,         -- version of the source row that was indexed
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, entity_type, entity_id)
) PARTITION BY HASH (workspace_id);

SELECT support_hash_partitions('search_documents', 8);

CREATE INDEX search_documents_tsv ON search_documents USING gin (tsv);

-- the query (add workspace_id filter + acl)
CREATE INDEX search_documents_acl ON search_documents USING gin (acl_node_ids);

-- node-set permission filter
CREATE INDEX search_documents_recent ON search_documents (workspace_id, entity_type, updated_at DESC);

-- =============================================================================
-- 9. PUBLIC API, webhooks, integrations, import/export  (Doc 3 section 16, FR-801..808, BRL-023, BRL-025, BRL-026)
-- =============================================================================
CREATE TABLE integrations (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  kind text NOT NULL,                                       -- slack, teams, github, gitlab, jira, calendar, zapier ...
  owner_id uuid REFERENCES users(id),
  identity_user_id uuid REFERENCES users(id),               -- FR-808 actions attributed to integration identity
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','needs_reconnect','paused','revoked')),
  secret_ref text,                                          -- vault reference, never the secret
  config jsonb NOT NULL DEFAULT '{}',
  needs_reconnect_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1
);

CREATE TABLE api_tokens (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id uuid REFERENCES users(id),
  name text NOT NULL,
  token_hash text NOT NULL UNIQUE,                          -- shown once, stored hashed (FR-802, SEC-015)
  prefix text NOT NULL,
  scopes text[] NOT NULL DEFAULT '{}',
  expires_at timestamptz, last_used_at timestamptz, revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE webhook_endpoints (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  url text NOT NULL,
  secret_ref text NOT NULL,                                 -- HMAC signing key reference (FR-803)
  event_types text[] NOT NULL,
  scope_container_id uuid REFERENCES containers(id),
  health text NOT NULL DEFAULT 'healthy' CHECK (health IN ('healthy','degraded','unhealthy','disabled')),
  consecutive_failures integer NOT NULL DEFAULT 0,
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1
);

CREATE TABLE webhook_deliveries (                           -- L-09, 30-day retention, partition by month
  workspace_id uuid NOT NULL,
  id uuid NOT NULL,
  endpoint_id uuid NOT NULL,
  event_id uuid NOT NULL,                                   -- change_log id
  attempt smallint NOT NULL DEFAULT 1,
  status_code integer, payload_hash text, error text,
  next_attempt_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, created_at, id)
) PARTITION BY RANGE (created_at);

SELECT support_month_partitions('webhook_deliveries', 1, 2);

CREATE TABLE webhook_deliveries_default PARTITION OF webhook_deliveries DEFAULT;

CREATE INDEX webhook_deliveries_retry ON webhook_deliveries (next_attempt_at) WHERE next_attempt_at IS NOT NULL;

CREATE TABLE idempotency_keys (                             -- Doc 3: Idempotency-Key on creates
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  key text NOT NULL, actor_id uuid, request_hash text NOT NULL,
  response_status integer, response_body jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, key)
);

CREATE TABLE inbound_email_addresses (                      -- FR-1108, FR-905
  address text PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  list_id uuid NOT NULL REFERENCES lists(id),
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE bug_details (
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  task_id uuid PRIMARY KEY REFERENCES tasks(id) ON DELETE CASCADE,
  severity text NOT NULL DEFAULT 'minor' CHECK (severity IN ('blocker','critical','major','minor','trivial')),
  steps_to_reproduce text, expected_result text, actual_result text, environment text,
  found_in_release_id uuid REFERENCES releases(id), fixed_in_release_id uuid REFERENCES releases(id),
  reproducible text CHECK (reproducible IN ('always','sometimes','rarely','unable')),
  root_cause text, duplicate_of_task_id uuid REFERENCES tasks(id),
  updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1
);

CREATE INDEX bug_details_sev ON bug_details (workspace_id, severity);

-- CORRECTION 6 Nov 2026: ClickUp has NO native budget or cost object. Cost and budget there are built by a tenant from Money custom fields,
-- Formula fields (rate x time tracked), automations and dashboards. So PARITY = tenant-defined custom fields + formulas over time tracked (a
-- requirement on our field engine). The cost_rates / budgets / expenses tables in section 1 are OUR OWN OPTIONAL ADD-ON, not parity. Keep them
-- out of phase 1 unless the client asks. Only "custom fields on people" is a plan-gated ClickUp feature (Business Plus).
-- Enterprise delta: cost management and AI (generated dashboards). Run AFTER frd-roles-permissions.sql and BEFORE rls.sql.
-- Source: client uses ClickUp Enterprise with time tracking, sprints, cost management, dependencies, many automations,
-- a little AI, and AI-generated dashboards (user statement 6 Nov 2026).
-- EVERYTHING HERE IS ASSUMED. We have NOT captured how ClickUp's own cost management or AI dashboards work (the playground is a
-- Business trial, not Enterprise). Treat as our design for the stated need, to be checked against what the client does today.

-- =============================================================================
-- 1. COST MANAGEMENT
-- Cost of work = tracked hours x cost rate (what the person costs us) and expenses. Billing = hours x billable rate (billable_rates, already exists).
-- Budget = an amount on a container compared with actual cost, billable amount, hours or points.
-- =============================================================================
CREATE TABLE cost_rates (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id uuid REFERENCES users(id),
  role_id uuid REFERENCES roles(id),                        -- rate by role when no user rate
  container_id uuid REFERENCES containers(id),              -- rate override inside a project
  rate_cents bigint NOT NULL CHECK (rate_cents >= 0),       -- per hour
  currency char(3) NOT NULL,
  effective_from date NOT NULL,
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (user_id IS NOT NULL OR role_id IS NOT NULL OR container_id IS NOT NULL)
);

-- rates never rewrite history: a new row with a later effective_from (FR-606)
CREATE INDEX cost_rates_lookup ON cost_rates (workspace_id, user_id, effective_from DESC);

-- from enterprise-delta.sql
ALTER TABLE time_entries ADD COLUMN cost_cents bigint;

-- from enterprise-delta.sql
-- snapshot at stop time, like rate_cents
ALTER TABLE time_entries ADD COLUMN cost_currency char(3);

CREATE TABLE budgets (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  container_id uuid NOT NULL REFERENCES containers(id),     -- space, folder or list (project)
  name text NOT NULL,
  basis text NOT NULL CHECK (basis IN ('cost','billable','hours','points')),
  amount bigint NOT NULL CHECK (amount >= 0),               -- cents, or minutes, or points x 100 depending on basis
  currency char(3),
  period_start date, period_end date,
  alert_thresholds smallint[] NOT NULL DEFAULT '{80,100}',  -- percent used, notify budget owner when crossed
  owner_id uuid REFERENCES users(id),
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1,
  CHECK (basis NOT IN ('cost','billable') OR currency IS NOT NULL),
  CHECK (period_end IS NULL OR period_start IS NULL OR period_end >= period_start)
);

CREATE INDEX budgets_container ON budgets (workspace_id, container_id) WHERE deleted_at IS NULL;

CREATE TABLE expenses (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  container_id uuid NOT NULL REFERENCES containers(id),
  task_id uuid REFERENCES tasks(id),
  user_id uuid NOT NULL REFERENCES users(id),               -- who incurred it
  category text, description text,
  amount_cents bigint NOT NULL CHECK (amount_cents >= 0),
  currency char(3) NOT NULL,
  incurred_on date NOT NULL,
  billable boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'submitted' CHECK (status IN ('draft','submitted','approved','rejected')),
  approved_by uuid REFERENCES users(id),
  receipt_file_id uuid REFERENCES files(id),
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1
);

CREATE INDEX expenses_container ON expenses (workspace_id, container_id, incurred_on) WHERE deleted_at IS NULL;

CREATE INDEX expenses_task ON expenses (workspace_id, task_id) WHERE task_id IS NOT NULL AND deleted_at IS NULL;

-- Daily roll-up so budget pages and widgets do not scan time_entries. Rebuilt by a worker, source of truth stays time_entries + expenses.
CREATE TABLE budget_daily_actuals (
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  budget_id uuid NOT NULL REFERENCES budgets(id) ON DELETE CASCADE,
  day date NOT NULL,
  cost_cents bigint NOT NULL DEFAULT 0, billable_cents bigint NOT NULL DEFAULT 0,
  minutes bigint NOT NULL DEFAULT 0, points numeric(12,2) NOT NULL DEFAULT 0,
  expense_cents bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (budget_id, day)
);

-- Where does the hourly amount used for cost come from? Per workspace, so each tenant chooses.
CREATE TABLE cost_settings (
  workspace_id uuid PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,
  rate_source text NOT NULL DEFAULT 'cost_rates' CHECK (rate_source IN ('cost_rates','people_field')),
  cost_people_field_id uuid REFERENCES people_field_defs(id),     -- used when rate_source = people_field
  billable_people_field_id uuid REFERENCES people_field_defs(id),
  default_currency char(3),
  updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1,
  CHECK (rate_source <> 'people_field' OR cost_people_field_id IS NOT NULL)
);

-- from enterprise-delta.sql
-- Project cost report: per container (project), per user, billable vs non-billable. Reads the snapshot columns when present.
CREATE OR REPLACE VIEW v_time_by_user_billable AS
SELECT te.workspace_id, te.list_id, te.user_id, te.billable,
       sum(te.duration_ms) / 3600000.0 AS hours,
       sum(te.cost_cents) AS cost_cents, sum(te.rate_cents * te.duration_ms / 3600000.0)::bigint AS billable_amount_cents
  FROM time_entries te
 WHERE te.deleted_at IS NULL AND te.ended_at IS NOT NULL
 GROUP BY te.workspace_id, te.list_id, te.user_id, te.billable;
